import re
import shutil
import subprocess
from pathlib import Path

EXPORT_SCRIPT = "/opt/payroll/bin/export_payroll.py"


def run_payroll_export_and_archive(pay_period: str, department: str, export_dir: str, archive_root: str) -> dict:
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", pay_period or ""):
        return {"ok": False, "error": "pay_period must be YYYY-MM"}
    if not re.fullmatch(r"[A-Z]{2,10}", department or ""):
        return {"ok": False, "error": "department must be an uppercase code"}
    export_path = Path(export_dir)
    if not export_path.is_dir():
        return {"ok": False, "error": "export_dir does not exist"}
    archive_path = Path(archive_root)
    if not archive_path.is_dir():
        return {"ok": False, "error": "archive_root does not exist"}

    result = subprocess.run(
        ["python3", EXPORT_SCRIPT, "--period", pay_period, "--dept", department, "--out", str(export_path)],
        capture_output=True,
        text=True,
        timeout=600,
    )
    if result.returncode != 0:
        return {"ok": False, "error": result.stderr.strip()[:500]}

    produced = export_path / f"payroll_{department}_{pay_period}.csv"
    if not produced.exists():
        return {"ok": False, "error": "export finished but no file was produced"}

    target_dir = archive_path / pay_period
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / produced.name
    if target.exists():
        return {"ok": False, "error": "archive file already exists"}

    shutil.move(str(produced), str(target))
    return {"ok": True, "archived_to": str(target)}

import sqlite3


def _remaining(allocated, used):
    return round(allocated - used, 2)


def get_employee_leave_balance(employee_id: int, year: int) -> dict:
    conn = sqlite3.connect("file:/var/data/hr.db?mode=ro", uri=True)
    conn.row_factory = sqlite3.Row
    rows = conn.execute(
        "SELECT leave_type, allocated_days, used_days FROM leave_balances WHERE employee_id = ? AND year = ?",
        (employee_id, year),
    ).fetchall()
    conn.close()
    balances = {r["leave_type"]: _remaining(r["allocated_days"], r["used_days"]) for r in rows}
    return {"employee_id": employee_id, "year": year, "balances": balances}

import sqlite3
from contextlib import closing

from mcp_instance import mcp


@mcp.tool()
def transfer_employee_department(employee_id: int, new_department_id: int, new_title: str) -> dict:
    with closing(sqlite3.connect("/var/data/hr.db")) as conn:
        with conn:
            cur = conn.execute(
                "UPDATE employees SET department_id = ?, job_title = ? WHERE id = ?",
                (new_department_id, new_title, employee_id),
            )
    if cur.rowcount == 0:
        return {"ok": False, "error": "employee not found"}
    return {"ok": True, "employee_id": employee_id, "department_id": new_department_id}
